                       '\n'
                       "describe('computeThresholds', () => {\n"
                       "  it('32K window — degenerate ceiling, proportional floor "
                       "governs auto', () => {\n"
                       '    // effectiveWindow 12K, ceiling = 12K - 13K = -1K (≤ 0) → '
                       'auto falls back to\n'
                       '    // the proportional floor (0.85 * 32K).\n'
                       '    const t = computeThresholds(32_000);\n'
                       '    expect(t.warn).toBe(7_200); // auto - WARN_BUFFER = 27.2K '
                       '- 20K\n'
                       '    expect(t.auto).toBe(27_200); // proportional floor: 0.85 * '
                       '32K\n'
                       '    expect(t.hard).toBe(30_200); // auto + HARD_BUFFER = 27.2K '
                       '+ 3K\n'
                       '    expect(t.effectiveWindow).toBe(12_000);\n'
                       '  });\n'
                       '\n'
                       "  it('60K window — ceiling governs auto; hard stays above auto "
                       "(issue #4945)', () => {\n"
                       '    // ceiling = ew(40K) - 13K = 27K < proportional(51K) → '
                       'auto = ceiling.\n'
                       '    const t = computeThresholds(60_000);\n'
                       '    expect(t.warn).toBe(7_000); // auto - WARN_BUFFER = 27K - '
                       '20K\n'
                       '    expect(t.auto).toBe(27_000); // min(0.85*60K=51K, '
                       'ew-13K=27K)\n'
                       '    expect(t.hard).toBe(37_000); // ew - HARD_BUFFER = 40K - '
                       '3K\n'
                       '    expect(t.hard).toBeGreaterThan(t.auto);\n'
                       '    expect(t.effectiveWindow).toBe(40_000);\n'
                       '  });\n'
                       '\n'
                       "  it('128K window — ceiling governs auto (leaves room to "
                       "compress)', () => {\n"
                       '    // ceiling = ew(108K) - 13K = 95K < proportional(108.8K) → '
                       'auto = ceiling.\n'
                       '    // auto + SUMMARY_RESERVE = 95K + 20K = 115K ≤ 128K, so '
                       'the summary fits.\n'
                       '    const t = computeThresholds(128_000);\n'
                       '    expect(t.warn).toBe(75_000); // auto - WARN_BUFFER = 95K - '
                       '20K\n'
                       '    expect(t.auto).toBe(95_000); // min(0.85*128K=108.8K, '
                       'ew-13K=95K)\n'
                       '    expect(t.hard).toBe(105_000); // ew - HARD_BUFFER = 108K - '
                       '3K\n'
                       '    expect(t.effectiveWindow).toBe(108_000);\n'
                       '  });\n'
                       '\n'
                       "  it('200K window — ceiling governs auto (167K), just below "
                       "proportional', () => {\n"
                       '    // ceiling = ew(180K) - 13K = 167K < proportional(170K) → '
                       'auto = 167K.\n'
                       '    const t = computeThresholds(200_000);\n'
                       '    expect(t.warn).toBe(147_000); // auto - WARN_BUFFER = 167K '
                       '- 20K\n'
                       '    expect(t.auto).toBe(167_000); // min(0.85*200K=170K, '
                       'ew-13K=167K)\n'
                       '    expect(t.hard).toBe(177_000); // ew - HARD_BUFFER = 180K - '
                       '3K\n'
                       '  });\n'
                       '\n'
                       "  it('1M window — proportional governs auto (85%), never "
                       "crowds the ceiling', () => {\n"
