                       '      const defaultResult = computeThresholds(1_000_000);\n'
                       '      const customPct = computeThresholds(1_000_000, 0.5);\n'
                       '      expect(defaultResult.auto).toBe(850_000); // 0.85 * 1M\n'
                       '      expect(customPct.auto).toBe(500_000); // 0.5 * 1M < '
                       'ceiling(967K)\n'
                       '      '
                       'expect(customPct.auto).toBeLessThan(defaultResult.auto);\n'
                       '    });\n'
                       '\n'
                       "    it('custom pct preserves warn <= auto < hard invariant', "
                       '() => {\n'
                       '      for (const pct of [0.3, 0.5, 0.6, 0.8, 0.9]) {\n'
                       '        for (const w of [10_000, 32_000, 128_000, 200_000]) {\n'
                       '          const t = computeThresholds(w, pct);\n'
                       '          expect(t.warn).toBeLessThanOrEqual(t.auto);\n'
                       '          expect(t.auto).toBeLessThan(t.hard);\n'
                       '        }\n'
                       '      }\n'
                       '    });\n'
                       '\n'
                       "    it('pct=0 produces auto=0 for small windows (proportional "
                       "floor is 0)', () => {\n"
                       '      const t = computeThresholds(32_000, 0);\n'
                       '      // 0 * 32000 = 0; ceiling is negative → auto = '
                       'proportional floor = 0.\n'
                       '      expect(t.auto).toBe(0);\n'
                       '      // warn = max(0, 0 - WARN_BUFFER) = 0\n'
                       '      expect(t.warn).toBeLessThanOrEqual(t.auto);\n'
