                      '    expect(harness.countCandidate.mock.calls[1]![3]).toEqual({\n'
                      '      tools: requestTools,\n'
                      '    });\n'
                      '  });\n'
                      '\n'
                      "  it('includes a pending tool result in the summary and "
                      "candidate requests', async () => {\n"
                      '    const harness = makeHarness();\n'
                      '    const toolCall: Content = {\n'
                      "      role: 'model',\n"
                      '      parts: [\n'
                      '        {\n'
