                      '      toolCall,\n'
                      '    ]);\n'
                      '    const pending: Content = {\n'
                      "      role: 'user',\n"
                      '      parts: [\n'
                      '        {\n'
                      '          functionResponse: {\n'
                      "            id: 'call-1',\n"
                      "            name: 'read_file',\n"
                      "            response: { output: 'contents' },\n"
                      '          },\n'
                      '        },\n'
                      '      ],\n'
                      '    };\n'
                      '\n'
                      '    await compress(harness, {\n'
                      '      force: false,\n'
                      "      trigger: 'auto',\n"
