                              "describe('ChatCompressionService.compress — single-turn "
                              "computer-use regression', () => {\n"
                              '  afterEach(() => {\n'
                              '    vi.restoreAllMocks();\n'
                              '  });\n'
                              '\n'
                              '  function makeFakeChat(history: Content[]): GeminiChat '
                              '{\n'
                              '    const getHistoryMock = '
                              'vi.fn().mockReturnValue(history);\n'
                              '    return {\n'
                              '      getHistory: getHistoryMock,\n'
                              '      getHistoryShallow: getHistoryMock,\n'
                              '    } as unknown as GeminiChat;\n'
                              '  }\n'
                              '\n'
                              '  function makeFakeConfig(): Config {\n'
                              '    return {\n'
                              '      getChatCompression: vi.fn(),\n'
                              '      getAutoCompactThreshold: vi.fn(),\n'
                              '      getBaseLlmClient: vi.fn(),\n'
                              '      getContentGeneratorConfig: vi\n'
                              '        .fn()\n'
                              '        .mockReturnValue({ contextWindowSize: 200_000 '
                              '}),\n'
                              '      getHookSystem: vi.fn().mockReturnValue({\n'
                              '        firePreCompactEvent: '
                              'vi.fn().mockResolvedValue(undefined),\n'
                              '        firePostCompactEvent: '
                              'vi.fn().mockResolvedValue(undefined),\n'
                              '      }),\n'
                              "      getModel: () => 'test-model',\n"
                              '      getAllConfiguredModels: '
                              'vi.fn().mockReturnValue([]),\n'
                              "      getApprovalMode: () => 'default',\n"
                              '      getDebugLogger: () => ({ warn: vi.fn(), debug: '
                              'vi.fn() }),\n'
                              "      getTargetDir: () => '/tmp/test-workspace',\n"
                              '    } as unknown as Config;\n'
                              '  }\n'
                              '\n'
                              "  it('preserves the user prompt verbatim in summary and "
                              "restores 3 most recent screenshots', async () => {\n"
                              '    // Reproduces the "single-turn long task" scenario '
                              'the rewrite targets:\n'
                              '    // ONE user message kicks off many tool calls. OLD '
                              'behavior with the\n'
                              '    // split-point model: 0 entries preserved verbatim '
                              'when compression\n'
                              '    // fires after a tool result (the common case). NEW '
                              'behavior: summary\n'
                              '    // contains the user prompt verbatim (via 9-section '
                              "prompt template's\n"
                              '    // "All user messages" section) + 3 most recent '
                              'screenshots attached\n'
                              '    // as the image restoration block.\n'
                              '    // Real shape: the screenshot is nested inside '
                              'functionResponse.parts,\n'
                              '    // exactly as '
                              'coreToolScheduler.convertToFunctionResponse emits it — '
                              'NOT\n'
                              '    // a top-level sibling. (The earlier sibling shape '
                              'masked the bug where\n'
                              '    // extractRecentImages restored zero screenshots.)\n'
                              '    const screenshot = (data: string): Content => ({\n'
                              "      role: 'user',\n"
                              '      parts: [\n'
                              '        {\n'
                              '          functionResponse: {\n'
                              "            name: 'computer_use__get_app_state',\n"
                              "            response: { output: 'ok' },\n"
                              '            parts: [{ inlineData: { mimeType: '
                              "'image/png', data } }],\n"
                              '          } as unknown as NonNullable<\n'
                              "            Content['parts']\n"
                              "          >[number]['functionResponse'],\n"
                              '        },\n'
                              '      ],\n'
                              '    });\n'
                              '    const callScreenshot = (app: string): Content => '
                              '({\n'
                              "      role: 'model',\n"
                              '      parts: [\n'
                              '        {\n'
                              '          functionCall: {\n'
                              "            name: 'computer_use__get_app_state',\n"
                              '            args: { app },\n'
                              '          },\n'
                              '        },\n'
                              '      ],\n'
                              '    });\n'
                              '\n'
                              '    const history: Content[] = [\n'
                              '      {\n'
                              "        role: 'user',\n"
                              "        parts: [{ text: 'open Safari and read the first "
                              "headline' }],\n"
                              '      },\n'
                              "      callScreenshot('Safari'),\n"
                              "      screenshot('s1'),\n"
                              "      callScreenshot('Safari'),\n"
                              "      screenshot('s2'),\n"
                              "      callScreenshot('Safari'),\n"
                              "      screenshot('s3'),\n"
                              "      callScreenshot('Safari'),\n"
                              "      screenshot('s4'),\n"
                              "      callScreenshot('Safari'),\n"
                              "      screenshot('s5'),\n"
                              '    ];\n'
                              '\n'
                              '    vi.spyOn(sideQueryModule, '
                              "'runSideQuery').mockResolvedValue({\n"
                              '      text: \'SUMMARY containing "open Safari and read '
                              'the first headline" verbatim\',\n'
                              '      usage: {\n'
                              '        promptTokenCount: 170_000,\n'
                              '        candidatesTokenCount: 500,\n'
                              '        totalTokenCount: 170_500,\n'
                              '      },\n'
                              '    } as never);\n'
                              '\n'
                              '    const service = new ChatCompressionService();\n'
                              '    const result = await '
                              'service.compress(makeFakeChat(history), {\n'
                              "      promptId: 'p',\n"
                              '      force: true,\n'
                              '      config: makeFakeConfig(),\n'
                              '      consecutiveFailures: 0,\n'
                              '      originalTokenCount: 180_000,\n'
                              "      trigger: 'manual',\n"
                              '    });\n'
                              '\n'
                              '    expect(result.newHistory).not.toBeNull();\n'
                              '    const flat = result.newHistory!;\n'
                              '    const flatText = flat\n'
                              '      .flatMap((c) => c.parts ?? [])\n'
                              "      .map((p) => (p as { text?: string }).text ?? '')\n"
                              "      .join('\\n');\n"
                              '\n'
                              '    // Assertion 1: summary text (mocked) carries the '
                              'user prompt verbatim.\n'
                              "    expect(flatText).toContain('open Safari and read "
                              "the first headline');\n"
                              '\n'
                              '    // Assertion 2: Image restoration block exists and '
                              'contains exactly s3, s4, s5\n'
                              '    // (the 3 most recent screenshots), in '
                              'chronological order.\n'
                              '    const inlineDataParts = flat.flatMap((c) =>\n'
                              '      (c.parts ?? []).filter((p) =>\n'
                              '        (\n'
                              '          p as { inlineData?: { mimeType?: string } }\n'
                              "        ).inlineData?.mimeType?.startsWith('image/'),\n"
                              '      ),\n'
                              '    );\n'
                              '    expect(\n'
                              '      inlineDataParts.map(\n'
                              '        (p) => (p as { inlineData: { data: string } '
                              '}).inlineData.data,\n'
                              '      ),\n'
                              "    ).toEqual(['s3', 's4', 's5']);\n"
                              '\n'
                              '    // Assertion 3: Image metadata header mentions the '
                              'source tool and args.\n'
                              '    '
                              "expect(flatText).toContain('computer_use__get_app_state');\n"
                              '    expect(flatText).toContain(\'"app":"Safari"\');\n'
                              '  });\n'
                              '});\n'
                              '\n'
                              "describe('ChatCompressionService.compress — "
                              "customInstructions plumbing', () => {\n"
                              '  afterEach(() => {\n'
                              '    vi.restoreAllMocks();\n'
                              '  });\n'
                              '\n'
                              '  // The HookSystem wrapper returns DefaultHookOutput | '
                              'undefined to consumers\n'
                              '  // (see hookSystem.ts:274-287). Source code calls '
                              '`result?.getAdditionalContext()`,\n'
                              '  // so mocks must expose that method — not the raw '
                              'AggregatedHookResult shape\n'
                              '  // that hookEventHandler returns. This tiny helper '
                              'builds a stand-in.\n'
