                             '    firePostCompactEvent,\n'
                             '  };\n'
                             '  const baseLlmClient = { countRequestTokens: '
                             'countSideQuery, generateText };\n'
                             '  const config = {\n'
                             '    getChatCompression: () => ({\n'
                             '      maxRecentFiles: 0,\n'
                             '      maxRecentImages: 0,\n'
                             '      enableScreenshotTrigger: false,\n'
                             '    }),\n'
                             '    getContentGeneratorConfig: () => '
                             'contentGeneratorConfig,\n'
                             '    getAutoCompactThreshold: () => autoThreshold,\n'
                             '    getHookSystem: () => (hooksEnabled ? hookSystem : '
                             'undefined),\n'
                             '    getCompactionModel: () => compactionModel,\n'
                             '    getModel: () => MODEL,\n'
                             '    getBaseLlmClient: () => baseLlmClient,\n'
                             '    getDebugLogger: () => ({ debug, warn }),\n'
                             "    getTargetDir: () => '/workspace',\n"
                             '    getApprovalMode: () => ApprovalMode.DEFAULT,\n'
                             '    getBackgroundTaskRegistry: () => undefined,\n'
                             '    getUsageStatisticsEnabled: () => false,\n'
                             "    getSessionId: () => 'compaction-test-session',\n"
                             '  } as unknown as Config;\n'
                             '  const chat = {\n'
                             '    getHistoryShallow: () => history.map((entry) => ({ '
                             '...entry })),\n'
                             '    getGenerationConfig: () => ({ ...generationConfig '
                             '}),\n'
                             '    countRequestTokensForCandidateHistory: '
                             'countCandidate,\n'
                             '  } as unknown as GeminiChat;\n'
                             '\n'
                             '  return {\n'
                             '    config,\n'
                             '    chat,\n'
                             '    get history() {\n'
                             '      return history;\n'
                             '    },\n'
                             '    countSideQuery,\n'
                             '    generateText,\n'
                             '    countCandidate,\n'
                             '    firePreCompactEvent,\n'
                             '    firePostCompactEvent,\n'
                             '    debug,\n'
                             '    warn,\n'
                             '    generationConfig,\n'
                             '    contentGeneratorConfig,\n'
                             '    setCompactionModel(model) {\n'
                             '      compactionModel = model;\n'
                             '    },\n'
                             '    setHistory(next) {\n'
                             '      history = next;\n'
                             '    },\n'
                             '    setAutoThreshold(value) {\n'
                             '      autoThreshold = value;\n'
                             '    },\n'
                             '    setHookSystem(enabled) {\n'
                             '      hooksEnabled = enabled;\n'
                             '    },\n'
                             '  };\n'
                             '}\n'
                             '\n'
                             'async function compress(\n'
                             '  harness: Harness,\n'
                             '  overrides: {\n'
                             '    force?: boolean;\n'
                             "    trigger?: 'manual' | 'auto';\n"
                             '    originalTokenCount?: number;\n'
                             '    pendingUserMessage?: Content;\n'
                             '    precomputedEffectiveTokens?: number;\n'
                             '    requestGenerationConfig?: GenerateContentConfig;\n'
                             '    customInstructions?: string;\n'
                             '    signal?: AbortSignal;\n'
                             '  } = {},\n'
                             ') {\n'
                             '  return new '
                             'ChatCompressionService().compress(harness.chat, {\n'
                             "    promptId: 'compaction-contract',\n"
                             '    force: overrides.force ?? true,\n'
                             '    trigger: overrides.trigger,\n'
                             '    config: harness.config,\n'
                             '    originalTokenCount: overrides.originalTokenCount ?? '
                             '230_000,\n'
                             '    pendingUserMessage: overrides.pendingUserMessage,\n'
                             '    precomputedEffectiveTokens: '
                             'overrides.precomputedEffectiveTokens,\n'
                             '    requestGenerationConfig: '
                             'overrides.requestGenerationConfig,\n'
                             '    customInstructions: overrides.customInstructions,\n'
                             '    signal: overrides.signal,\n'
                             '  });\n'
                             '}\n'
                             '\n'
                             "describe('computeThresholds', () => {\n"
                             "  it('uses the exact native-window ladder selected by "
                             "the deployment', () => {\n"
                             '    expect(computeThresholds(WINDOW, 1)).toEqual({\n'
                             '      effectiveWindow: WINDOW - SUMMARY_RESERVE,\n'
                             '      warn: WINDOW - SUMMARY_RESERVE - '
                             'AUTOCOMPACT_BUFFER - WARN_BUFFER,\n'
                             '      auto: WINDOW - SUMMARY_RESERVE - '
                             'AUTOCOMPACT_BUFFER,\n'
                             '      hard: WINDOW - SUMMARY_RESERVE - HARD_BUFFER,\n'
                             '    });\n'
                             '  });\n'
                             '\n'
                             '  it.each([32_000, 60_000, 128_000, 200_000, '
                             '1_000_000])(\n'
                             "    'keeps ordered non-negative thresholds for "
                             "window=%i',\n"
                             '    (window) => {\n'
                             '      const thresholds = computeThresholds(window);\n'
                             '      '
                             'expect(thresholds.warn).toBeGreaterThanOrEqual(0);\n'
                             '      '
                             'expect(thresholds.warn).toBeLessThanOrEqual(thresholds.auto);\n'
                             '      '
                             'expect(thresholds.auto).toBeLessThanOrEqual(thresholds.hard);\n'
                             '      '
                             'expect(thresholds.hard).toBeLessThanOrEqual(window);\n'
                             '    },\n'
                             '  );\n'
                             '\n'
                             "  it('uses DEFAULT_PCT for non-finite input and clamps "
                             "percentages', () => {\n"
                             '    expect(computeThresholds(1_000_000, '
                             'Number.NaN).auto).toBe(\n'
                             '      DEFAULT_PCT * 1_000_000,\n'
                             '    );\n'
                             '    expect(computeThresholds(10_000, -1).auto).toBe(0);\n'
                             '    expect(computeThresholds(10_000, '
                             '2).auto).toBe(10_000);\n'
                             '  });\n'
                             '});\n'
                             '\n'
                             "describe('ChatCompressionService single exact mode', () "
                             '=> {\n'
                             '  beforeEach(() => {\n'
                             '    vi.restoreAllMocks();\n'
                             '    vi.spyOn(attachments, '
                             "'composePostCompactHistory').mockResolvedValue([\n"
                             "      { role: 'user', parts: [{ text: "
                             "snapshot('replacement') }] },\n"
                             "      { role: 'model', parts: [{ text: 'ack' }] },\n"
                             '    ]);\n'
                             '  });\n'
                             '\n'
                             "  it('NOOPs before side effects when history or "
                             "threshold state cannot compact', async () => {\n"
                             '    const empty = makeHarness();\n'
                             '    empty.setHistory([]);\n'
                             '    expect((await '
                             'compress(empty)).info.compressionStatus).toBe(\n'
                             '      CompressionStatus.NOOP,\n'
                             '    );\n'
                             '    expect(empty.generateText).not.toHaveBeenCalled();\n'
                             '\n'
                             '    const oneTurn = makeHarness();\n'
                             "    oneTurn.setHistory([{ role: 'user', parts: [{ text: "
                             "'only one' }] }]);\n"
                             '    expect((await '
                             'compress(oneTurn)).info.compressionStatus).toBe(\n'
                             '      CompressionStatus.NOOP,\n'
                             '    );\n'
                             '\n'
                             '    const below = makeHarness();\n'
                             '    below.setAutoThreshold(1);\n'
                             '    '
                             'below.countCandidate.mockReset().mockResolvedValue({\n'
                             '      totalTokens: 100_000,\n'
                             '      maxModelLen: WINDOW,\n'
                             '    });\n'
                             '    expect(\n'
                             '      (\n'
                             '        await compress(below, {\n'
                             '          force: false,\n'
                             '          originalTokenCount: 100_000,\n'
                             '        })\n'
                             '      ).info.compressionStatus,\n'
                             '    ).toBe(CompressionStatus.NOOP);\n'
                             '    expect(below.countCandidate).toHaveBeenCalledWith(\n'
                             '      below.history,\n'
                             '      undefined,\n'
                             "      'compaction-contract:auto-threshold',\n"
                             '      undefined,\n'
                             '    );\n'
                             '\n'
                             '    // Nothing suppresses an over-threshold attempt. The '
                             'consecutive-failure\n'
                             '    // breaker that NOOPed here walked a real session '
                             'through the hard limit\n'
                             '    // while its context kept growing; every trigger now '
                             'runs an attempt.\n'
                             '    const stillTries = makeHarness();\n'
                             '    const { auto } = computeThresholds(WINDOW, 1);\n'
                             '    expect(\n'
                             '      (\n'
                             '        await compress(stillTries, {\n'
                             '          force: false,\n'
                             '          precomputedEffectiveTokens: auto,\n'
                             '        })\n'
                             '      ).info.compressionStatus,\n'
                             '    ).toBe(CompressionStatus.COMPRESSED);\n'
                             '    '
                             'expect(stillTries.generateText).toHaveBeenCalledTimes(1);\n'
                             '  });\n'
                             '\n'
                             "  it('sends the ENTIRE history to one cache-preserving "
                             "main-model request', async () => {\n"
                             '    const harness = makeHarness();\n'
                             '    const requestTools = [\n'
                             "      { functionDeclarations: [{ name: 'transient_tool' "
                             '}] },\n'
                             '    ];\n'
                             '    const result = await compress(harness, {\n'
                             '      requestGenerationConfig: { tools: requestTools },\n'
                             "      customInstructions: 'Preserve the exact unresolved "
                             "implementation state.',\n"
                             '    });\n'
                             '\n'
                             '    expect(result.info).toMatchObject({\n'
                             '      compressionStatus: CompressionStatus.COMPRESSED,\n'
                             '      originalTokenCount: 230_000,\n'
                             '      newTokenCount: 12_000,\n'
                             '      newTokenCountIsEstimated: false,\n'
                             '    });\n'
                             '    '
                             'expect(harness.countSideQuery).toHaveBeenCalledTimes(1);\n'
                             '    '
                             'expect(harness.generateText).toHaveBeenCalledTimes(1);\n'
                             '    '
                             'expect(harness.countCandidate).toHaveBeenCalledTimes(2);\n'
                             '\n'
                             '    const counted = harness.countSideQuery.mock\n'
                             '      .calls[0]![0] as GenerateTextOptions;\n'
                             '    const generated = harness.generateText.mock\n'
                             '      .calls[0]![0] as GenerateTextOptions;\n'
                             '    // One request shape renders both the count and the '
                             'generation; the output\n'
                             '    // budget is the single field the count has no use '
                             'for.\n'
                             '    const { maxOutputTokens, ...generatedConfig } = '
                             'generated.config as Record<\n'
                             '      string,\n'
                             '      unknown\n'
                             '    >;\n'
                             '    expect({ ...generated, config: generatedConfig '
                             '}).toEqual(counted);\n'
                             '    '
                             'expect(maxOutputTokens).toBe(COMPACT_MAX_OUTPUT_TOKENS);\n'
                             '    expect(generated).toMatchObject({\n'
                             '      model: MODEL,\n'
                             '      stream: true,\n'
                             '      maxAttempts: 1,\n'
                             '      promptCacheSharing: true,\n'
                             '      failClosed: true,\n'
                             '      config: {\n'
                             '        tools: requestTools,\n'
                             '        toolConfig: {\n'
                             '          functionCallingConfig: {\n'
                             '            mode: FunctionCallingConfigMode.NONE,\n'
                             '          },\n'
                             '        },\n'
                             '      },\n'
                             '    });\n'
                             '    // The request must be a pure extension of the '
                             'conversation already in\n'
                             "    // the provider's prefix cache: the same contents, "
                             'in the same order,\n'
                             '    // plus exactly one trailing directive. Anything '
                             'that rewrote, reordered\n'
                             '    // or dropped an earlier entry would re-prefill '
                             '~200K tokens and evict\n'
                             '    // the cache the agent needs on its very next turn. '
                             'It also declares no\n'
                             '    // phase budgets, so the model thinks and answers as '
                             'it does on any turn.\n'
                             '    '
                             'expect(generated.contents).toHaveLength(harness.history.length '
                             '+ 1);\n'
                             '    expect(generated.contents.slice(0, '
                             '-1)).toEqual(harness.history);\n'
                             '    const directive = '
                             "generated.contents.at(-1)?.parts?.[0]?.text ?? '';\n"
                             "    expect(directive).toContain('native hidden-thinking "
                             "channel');\n"
                             "    expect(directive).toContain('Do not call tools');\n"
                             "    expect(directive).toContain('Preserve the exact "
                             "unresolved');\n"
                             '\n'
                             '    '
                             'expect(harness.countCandidate.mock.calls[0]![3]).toEqual({\n'
                             '      tools: requestTools,\n'
                             '    });\n'
                             '    '
                             'expect(harness.countCandidate.mock.calls[1]![3]).toEqual({\n'
                             '      tools: requestTools,\n'
                             '    });\n'
                             '  });\n'
                             '\n'
                             "  it('includes a pending tool result in the summary and "
                             "candidate requests', async () => {\n"
                             '    const harness = makeHarness();\n'
                             '    const toolCall: Content = {\n'
                             "      role: 'model',\n"
                             '      parts: [\n'
                             '        {\n'
                             '          functionCall: {\n'
                             "            id: 'call-1',\n"
                             "            name: 'read_file',\n"
                             "            args: { path: 'README.md' },\n"
                             '          },\n'
                             '        },\n'
                             '      ],\n'
                             '    };\n'
                             '    harness.setHistory([\n'
                             "      { role: 'user', parts: [{ text: 'Read the file.' "
                             '}] },\n'
                             '      toolCall,\n'
                             '    ]);\n'
                             '    const pending: Content = {\n'
                             "      role: 'user',\n"
                             '      parts: [\n'
                             '        {\n'
                             '          functionResponse: {\n'
                             "            id: 'call-1',\n"
                             "            name: 'read_file',\n"
                             "            response: { output: 'contents' },\n"
                             '          },\n'
                             '        },\n'
                             '      ],\n'
                             '    };\n'
                             '\n'
                             '    await compress(harness, {\n'
                             '      force: false,\n'
                             "      trigger: 'auto',\n"
                             '      pendingUserMessage: pending,\n'
                             '      precomputedEffectiveTokens: 240_000,\n'
                             '      originalTokenCount: 240_000,\n'
                             '    });\n'
                             '\n'
                             '    const generated = harness.generateText.mock\n'
                             '      .calls[0]![0] as GenerateTextOptions;\n'
                             '    expect(generated.contents.slice(0, 3)).toEqual([\n'
                             '      harness.history[0],\n'
                             '      toolCall,\n'
                             '      pending,\n'
                             '    ]);\n'
                             '    '
                             'expect(harness.countCandidate.mock.calls[0]![1]).toBe(pending);\n'
                             '    '
                             'expect(harness.countCandidate.mock.calls[1]![1]).toBe(pending);\n'
                             '    '
                             'expect(attachments.composePostCompactHistory).toHaveBeenCalledWith(\n'
                             '      harness.history,\n'
                             '      snapshot(),\n'
                             '      expect.any(Object),\n'
                             '    );\n'
                             '  });\n'
                             '\n'
                             "  it('keeps ordinary pending user text out of the "
                             "summary but in both exact commit counts', async () => {\n"
                             '    const harness = makeHarness();\n'
                             '    const pending: Content = {\n'
                             "      role: 'user',\n"
                             "      parts: [{ text: 'This new request must survive "
                             "compaction.' }],\n"
                             '    };\n'
                             '    await compress(harness, { pendingUserMessage: '
                             'pending });\n'
                             '\n'
                             '    const generated = harness.generateText.mock\n'
                             '      .calls[0]![0] as GenerateTextOptions;\n'
                             '    expect(generated.contents).not.toContain(pending);\n'
                             '    '
                             'expect(harness.countCandidate.mock.calls[0]![1]).toBe(pending);\n'
                             '    '
                             'expect(harness.countCandidate.mock.calls[1]![1]).toBe(pending);\n'
                             '  });\n'
                             '\n'
                             "  it('preserves inline images in the cache-sharing "
                             "request', async () => {\n"
                             '    const harness = makeHarness();\n'
                             '    const image = {\n'
                             "      inlineData: { mimeType: 'image/png', data: "
                             "'aW1hZ2U=' },\n"
                             '    };\n'
                             '    harness.setHistory([\n'
                             "      { role: 'user', parts: [{ text: 'Inspect this.' }, "
                             'image] },\n'
                             "      { role: 'model', parts: [{ text: 'I inspected it.' "
                             '}] },\n'
                             '    ]);\n'
                             '    await compress(harness);\n'
                             '    const generated = harness.generateText.mock\n'
                             '      .calls[0]![0] as GenerateTextOptions;\n'
                             '    '
                             'expect(generated.contents[0]?.parts).toContainEqual(image);\n'
                             '  });\n'
                             '\n'
                             "  it('closes a manual dangling tool call with an "
                             "unknown-outcome result', async () => {\n"
                             '    const harness = makeHarness();\n'
                             '    harness.setHistory([\n'
                             "      { role: 'user', parts: [{ text: 'Modify the file.' "
                             '}] },\n'
                             '      {\n'
                             "        role: 'model',\n"
                             '        parts: [\n'
                             '          {\n'
                             '            functionCall: {\n'
                             "              id: 'write-1',\n"
                             "              name: 'write_file',\n"
                             "              args: { path: 'a.ts' },\n"
                             '            },\n'
                             '          },\n'
                             '        ],\n'
                             '      },\n'
                             '    ]);\n'
                             '\n'
                             "    await compress(harness, { trigger: 'manual' });\n"
                             '    const preHistory = '
                             'harness.countCandidate.mock.calls[0]![0] as Content[];\n'
                             '    const closure = '
                             'preHistory.at(-1)?.parts?.[0]?.functionResponse;\n'
                             '    expect(closure).toMatchObject({\n'
                             "      id: 'write-1',\n"
                             "      name: 'write_file',\n"
                             '      response: { error: ORPHAN_TOOL_USE_REPAIR_REASON '
                             '},\n'
