                      '      return {\n'
                      '        newHistory: null,\n'
                      '        info: {\n'
                      '          originalTokenCount: exactOriginalTokenCount,\n'
                      '          newTokenCount: exactOriginalTokenCount,\n'
                      '          compressionStatus: '
                      'CompressionStatus.COMPRESSION_FAILED_EMPTY_SUMMARY,\n'
                      '          output: outputAccounting,\n'
                      '        },\n'
                      '      };\n'
                      '    }\n'
                      '    if (summaryResult.hadToolCall || '
                      '!hasStateSnapshot(processedSummary)) {\n'
                      '      config\n'
                      '        .getDebugLogger()\n'
                      '        .warn(\n'
                      '          `[chat-compression] STOP response violated the '
                      'summary contract ` +\n'
                      "            `(${summaryResult.hadToolCall ? 'unexpected tool "
                      "call' : 'invalid state_snapshot'}); preserving original "
                      'history.`,\n'
                      '        );\n'
                      '      return {\n'
                      '        newHistory: null,\n'
                      '        info: {\n'
                      '          originalTokenCount: exactOriginalTokenCount,\n'
                      '          newTokenCount: exactOriginalTokenCount,\n'
                      '          compressionStatus:\n'
                      '            '
                      'CompressionStatus.COMPRESSION_FAILED_PROTOCOL_ERROR,\n'
                      '          output: outputAccounting,\n'
                      '        },\n'
                      '      };\n'
                      '    }\n'
                      '\n'
                      '    let extraHistory: Content[];\n'
                      '    try {\n'
                      '      extraHistory = await composePostCompactHistory(\n'
                      "        compactTrigger === 'manual' ? historyForSummary : "
                      'curatedHistory,\n'
                      '        summary,\n'
                      '        {\n'
                      '          workspaceRoot: config.getTargetDir(),\n'
                      '          signal,\n'
                      '          maxFiles: tuning.maxRecentFiles,\n'
                      '          maxImages: tuning.maxRecentImages,\n'
                      '          planModeActive: config.getApprovalMode?.() === '
                      'ApprovalMode.PLAN,\n'
                      '          runningSubagents: collectActiveSubagents(config),\n'
                      '        },\n'
                      '      );\n'
                      '    } catch (error) {\n'
                      '      config\n'
                      '        .getDebugLogger()\n'
                      '        .warn(\n'
                      '          `[chat-compression] post-compact history assembly '
