                       '\n'
                       'const MAX_PDF_TEXT_OUTPUT_CHARS = 100000;\n'
                       'const PDF_FULL_TEXT_PAGE_LIMIT = 10;\n'
                       'export const PDF_MAX_PAGES_PER_READ = 20;\n'
                       'const PDF_PAGE_COUNT_SIZE_HEURISTIC_BYTES = 100 * 1024;\n'
                       'export const PDF_TEXT_RESULT_MAX_TOKENS = 12_000;\n'
                       'const PDF_TEXT_RESULT_WRAPPER_TOKEN_CHARS = 64;\n'
                       'const PDF_TEXT_RESULT_CHARS_PER_TOKEN = 4;\n'
                       'export const PDF_TEXT_EXTRACTION_UNAVAILABLE_MESSAGE =\n'
                       "  'pdftotext is not installed. Install poppler-utils to enable "
                       'PDF text extraction (e.g. `apt-get install poppler-utils` or '
                       "`brew install poppler`).';\n"
                       'export const PDF_RENDER_UNAVAILABLE_MESSAGE =\n'
                       "  'pdftoppm is not installed. Install poppler-utils to enable "
                       'PDF page rendering (e.g. `apt-get install poppler-utils` or '
                       "`brew install poppler`).';\n"
                       '/**\n'
                       ' * Longest-edge pixel cap passed to `pdftoppm -scale-to`. '
                       'Bounds each rendered\n'
