                       '\n'
                       "  describe('boolean string coercion', () => {\n"
                       '    const booleanSchema = {\n'
                       "      type: 'object',\n"
                       '      properties: {\n'
                       '        is_background: {\n'
                       "          type: 'boolean',\n"
                       '        },\n'
                       '      },\n'
