                       '    it(\'should coerce string "TRUE" to boolean true\', () => '
                       '{\n'
                       "      const params = { is_background: 'TRUE' };\n"
                       '      expect(SchemaValidator.validate(booleanSchema, '
                       'params)).toBeNull();\n'
                       '      expect(params.is_background).toBe(true);\n'
                       '    });\n'
                       '\n'
                       '    it(\'should coerce string "false" to boolean false\', () '
