                       "      const params = { is_background: 'FALSE' };\n"
                       '      expect(SchemaValidator.validate(booleanSchema, '
                       'params)).toBeNull();\n'
                       '      expect(params.is_background).toBe(false);\n'
                       '    });\n'
                       '\n'
                       "    it('should handle nested objects with string booleans', () "
