                       '      expect(params.flags).toEqual([true, false, true]);\n'
                       '    });\n'
                       '\n'
                       "    it('should pass through actual boolean values unchanged', "
                       '() => {\n'
                       '      const params = { is_background: true };\n'
                       '      expect(SchemaValidator.validate(booleanSchema, '
                       'params)).toBeNull();\n'
                       '      expect(params.is_background).toBe(true);\n'
                       '    });\n'
                       '  });\n'
                       '\n'
