                       '\n'
                       "  describe('getEffectiveProperties prototype pollution guard', "
                       '() => {\n'
                       "    it('should not coerce data via __proto__-polluted property "
                       "prototype', () => {\n"
                       '      // Critical: a malicious MCP schema can register\n'
                       '      // `properties: {__proto__: {trigger_field: {type: '
                       "'boolean'}}, safe: ...}`.\n"
                       "      // With the unfixed code, `merged['__proto__'] = v` on a "
                       'plain `{}`\n'
                       '      // triggers the prototype setter, polluting `merged` '
                       'with `trigger_field`.\n'
                       "      // A subsequent lookup of `merged['trigger_field']` (for "
                       'a data key not\n'
                       '      // actually defined in the schema) returns the polluted '
                       'schema and\n'
                       "      // coerces a legitimate 'true' string to boolean.\n"
                       '      //\n'
                       '      // The fix uses Object.create(null) (no prototype chain '
                       'to pollute)\n'
                       '      // AND skips dangerous keys '
                       '(__proto__/constructor/prototype) during\n'
                       '      // the copy.\n'
                       '      //\n'
                       '      // A safe sibling property is included so that '
                       'getEffectiveProperties\n'
                       '      // returns a non-undefined value (the early-return check '
                       'is\n'
                       '      // `Object.keys(merged).length > 0`; without a sibling, '
                       'the polluted\n'
                       '      // merged has zero own keys and is treated as empty).\n'
                       '      //\n'
                       "      // A required 'bad' field forces Ajv to fail initially "
                       'so the coercion\n'
                       '      // passes actually run.\n'
                       '      //\n'
                       '      // JSON.parse is used to make __proto__ an OWN '
                       'enumerable property.\n'
                       '      // Object-literal `{__proto__: ...}` would set the '
                       'prototype chain\n'
                       '      // instead and defeat the test.\n'
                       '      const schema = JSON.parse(`{\n'
                       '        "type": "object",\n'
                       '        "properties": {\n'
                       '          "__proto__": { "trigger_field": { "type": "boolean" '
                       '} },\n'
                       '          "safe": { "type": "string" },\n'
                       '          "bad": { "type": "string" }\n'
                       '        },\n'
                       '        "required": ["bad"]\n'
                       '      }`);\n'
                       '      // Sanity: __proto__ is an own property of '
                       'schema.properties\n'
                       '      expect(Object.hasOwn(schema.properties, '
                       "'__proto__')).toBe(true);\n"
                       '\n'
                       '      // trigger_field is not a real property of the schema. '
                       'It happens to\n'
                       "      // match a field inside the __proto__'s value. bad is a "
                       'number, schema\n'
                       '      // expects a string — Ajv fails, triggering coercion.\n'
                       "      const params = { trigger_field: 'true', bad: 5 };\n"
                       '      expect(() => SchemaValidator.validate(schema, '
                       'params)).not.toThrow();\n'
                       "      // Without the fix: 'true' would be coerced to true via "
                       'the polluted\n'
                       '      // prototype. With the fix: trigger_field is not in the '
                       "schema's own\n"
                       '      // properties and the value stays as a string.\n'
                       "      expect(params.trigger_field).toBe('true');\n"
                       '      // bad should still coerce normally to its expected '
                       'string type.\n'
                       "      expect(params.bad).toBe('5');\n"
                       '    });\n'
                       '\n'
                       "    it('should still coerce legitimate sibling keys when "
                       "__proto__ is in properties', () => {\n"
                       '      // Defence-in-depth: even if __proto__ is present, '
                       'legitimate sibling\n'
                       '      // keys must still coerce normally.\n'
                       '      const schema = JSON.parse(`{\n'
                       '        "type": "object",\n'
                       '        "properties": {\n'
                       '          "__proto__": { "type": "boolean" },\n'
                       '          "legitimate": { "type": "string" }\n'
                       '        }\n'
                       '      }`);\n'
                       '      const params = { legitimate: 42 };\n'
                       '      expect(() => SchemaValidator.validate(schema, '
                       'params)).not.toThrow();\n'
                       "      expect(params.legitimate).toBe('42');\n"
                       '      // Object.prototype must not be modified either.\n'
                       '      expect(\n'
                       '        (Object.prototype as Record<string, '
                       "unknown>)['polluted'],\n"
                       '      ).toBeUndefined();\n'
                       '    });\n'
                       '\n'
                       "    it('should skip constructor and prototype keys as own "
                       "properties', () => {\n"
                       '      // Use JSON.parse to make constructor/prototype OWN '
                       'enumerable properties.\n'
                       '      // Include a sibling so getEffectiveProperties returns '
                       'non-undefined.\n'
                       '      const schema = JSON.parse(`{\n'
                       '        "type": "object",\n'
                       '        "properties": {\n'
                       '          "constructor": { "type": "boolean" },\n'
                       '          "prototype": { "type": "string" },\n'
                       '          "name": { "type": "string" }\n'
                       '        }\n'
                       '      }`);\n'
                       '      // Sanity: all three are own properties of '
                       'schema.properties\n'
                       '      expect(Object.hasOwn(schema.properties, '
