                              '    const entry = prefixItems[index];\n'
                              "    if (typeof entry === 'object' && entry !== null && "
                              '!Array.isArray(entry)) {\n'
                              '      return resolvePropSchema(entry, rootSchema);\n'
                              '    }\n'
                              '    return undefined;\n'
                              '  }\n'
                              "  const itemsSchema = parentSchema['items'] as\n"
                              '    | Record<string, unknown>\n'
                              '    | undefined;\n'
                              '  if (itemsSchema) {\n'
                              '    return resolvePropSchema(itemsSchema, rootSchema);\n'
                              '  }\n'
                              '  return undefined;\n'
                              '}\n'
                              '\n'
                              '/**\n'
                              ' * Collects subschemas from composition keywords '
                              '(allOf, anyOf, oneOf).\n'
                              ' * Used to find properties/additionalProperties/items '
                              'buried inside\n'
                              ' * composition wrappers so coercion can recurse into '
                              'nested objects.\n'
                              ' */\n'
                              'function getCompositionVariants(\n'
                              '  schema: Record<string, unknown>,\n'
                              '  rootSchema?: Record<string, unknown>,\n'
                              '): Array<Record<string, unknown>> {\n'
                              '  const variants: Array<Record<string, unknown>> = [];\n'
                              "  for (const keyword of ['allOf', 'anyOf', 'oneOf']) {\n"
                              '    const val = schema[keyword];\n'
                              '    if (Array.isArray(val)) {\n'
                              '      for (const item of val) {\n'
                              "        if (typeof item === 'object' && item != null && "
                              '!Array.isArray(item)) {\n'
                              '          // Resolve $ref on each variant so callers '
                              'see the effective schema\n'
